SELECT COUNT(DISTINCT `from`) AS distinct_sender_count FROM enron_emailinfo
SELECT COUNT(DISTINCT id) AS total_emails FROM enron_email
SELECT id, messageid, `from` FROM enron_emailinfo WHERE subject IS NULL OR TRIM(subject) = '' ORDER BY id ASC
SELECT COUNT(*) AS reply_by_orig_only FROM (SELECT DISTINCT id FROM enron_emailorig WHERE id NOT IN (SELECT id FROM enron_emailinfo WHERE subject LIKE 'Re:%' OR subject LIKE 'RE:%' OR subject LIKE 're:%')) AS t
SELECT COUNT(*) AS total_emails_sent FROM enron_emailinfo WHERE `from` = 'phillip.allen@enron.com' OR xfrom = 'Phillip K Allen'
SELECT mailbox, COUNT(*) AS cnt FROM enron_email GROUP BY mailbox ORDER BY cnt DESC LIMIT 10
SELECT COUNT(*) AS email_count FROM enron_email WHERE mailbox = 'sent'
SELECT COUNT(*) AS cnt FROM enron_emailinfo WHERE body LIKE '%California%'
SELECT id, source_file_id, source_name FROM enron_source ORDER BY id ASC LIMIT 10
SELECT DISTINCT mailbox FROM enron_email WHERE mailbox IS NOT NULL AND mailbox != '' ORDER BY mailbox ASC
SELECT id, date, subject, `from` FROM enron_emailinfo WHERE date IS NOT NULL AND date != '' AND CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(date, ' ', 4), ' ', -1) AS UNSIGNED) < 2010 ORDER BY CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(date, ' ', 4), ' ', -1) AS UNSIGNED) DESC, FIELD(SUBSTRING_INDEX(SUBSTRING_INDEX(date, ' ', 3), ' ', -1), 'Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec') DESC, CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(date, ' ', 2), ' ', -1) AS UNSIGNED) DESC, SUBSTRING_INDEX(SUBSTRING_INDEX(date, ' ', -1), ':', 1) DESC, SUBSTRING_INDEX(SUBSTRING(date, LOCATE(':', date)+1, 2), ':', 1) DESC, SUBSTRING(date, LOCATE(':', date)+4, 2) DESC LIMIT 10
SELECT COUNT(DISTINCT id) AS email_count FROM enron_emailinfo WHERE date LIKE '%2001%'
SELECT COUNT(*) AS total_rows, SUM(CASE WHEN xfrom IS NULL THEN 1 ELSE 0 END) AS xfrom_null, SUM(CASE WHEN xfrom = '' THEN 1 ELSE 0 END) AS xfrom_empty, SUM(CASE WHEN xto IS NULL THEN 1 ELSE 0 END) AS xto_null, SUM(CASE WHEN xto = '' THEN 1 ELSE 0 END) AS xto_empty FROM enron_emailorig
SELECT DISTINCT xfilename, xorigin FROM enron_source WHERE xfilename != '' ORDER BY xorigin
SELECT COUNT(DISTINCT mailbox) AS distinct_non_empty_mailbox_count FROM enron_email WHERE people = 'campbell-l' AND mailbox IS NOT NULL AND mailbox != ''
SELECT COUNT(DISTINCT id) AS cnt FROM enron_email GROUP BY mailbox ORDER BY cnt DESC LIMIT 1
SELECT COUNT(*) AS email_count FROM enron_emailinfo WHERE LOWER(subject) LIKE '%meeting%'
SELECT LOWER(TRIM(`from`)) AS sender, COUNT(DISTINCT id) AS email_count FROM enron_emailinfo WHERE `from` IS NOT NULL AND TRIM(`from`) != '' GROUP BY LOWER(TRIM(`from`)) HAVING COUNT(DISTINCT id) > 100 ORDER BY email_count DESC, sender ASC
SELECT TRIM(xfrom) AS xfrom_display, COUNT(DISTINCT id) AS email_count FROM enron_emailinfo WHERE xfrom IS NOT NULL AND TRIM(xfrom) != '' GROUP BY TRIM(xfrom) ORDER BY email_count DESC, xfrom_display ASC LIMIT 10
SELECT e.id, e.nnn, i.subject, i.`from` FROM enron_email e JOIN enron_emailinfo i ON e.id = i.id WHERE e.people = 'campbell-l' AND e.mailbox = 'all_documents' AND e.nnn IS NOT NULL ORDER BY e.nnn DESC, e.id DESC LIMIT 10
SELECT people, mailbox, COUNT(*) AS cnt FROM enron_email GROUP BY people, mailbox ORDER BY cnt DESC
SELECT et.`to` AS recipient, COUNT(*) AS cnt FROM enron_emailinfo ei JOIN enron_emailto et ON ei.id = et.id WHERE ei.`from` = 'phillip.allen@enron.com' GROUP BY et.`to` ORDER BY cnt DESC LIMIT 10
SELECT e.xfrom AS sender, COUNT(DISTINCT e.id) AS email_count FROM enron_emailinfo e WHERE LOWER(e.body) LIKE '%california%' GROUP BY e.xfrom ORDER BY email_count DESC LIMIT 5
SELECT xorigin, COUNT(DISTINCT xfolder) AS folder_count FROM enron_source WHERE xorigin IS NOT NULL AND xorigin != '' AND xfolder IS NOT NULL GROUP BY xorigin ORDER BY folder_count DESC, xorigin ASC
SELECT ei.`from` AS sender, COUNT(DISTINCT ei.id) AS email_count, AVG(rcpt_cnt.cnt) AS avg_recipients FROM enron_emailinfo ei JOIN ( SELECT id, COUNT(*) AS cnt FROM enron_emailto GROUP BY id ) rcpt_cnt ON ei.id = rcpt_cnt.id GROUP BY ei.`from` HAVING AVG(rcpt_cnt.cnt) > 3 ORDER BY avg_recipients DESC
SELECT (SELECT COUNT(DISTINCT id) FROM enron_email WHERE mailbox = 'sent') AS sent_count, (SELECT COUNT(DISTINCT id) FROM enron_email) AS total_count
SELECT `to` AS recipient, COUNT(DISTINCT id) AS email_count FROM enron_emailto GROUP BY `to` ORDER BY email_count DESC LIMIT 10
SELECT LPAD( CASE SUBSTRING_INDEX(SUBSTRING_INDEX(date, ' ', 3), ' ', -1) WHEN 'Jan' THEN 1 WHEN 'Feb' THEN 2 WHEN 'Mar' THEN 3 WHEN 'Apr' THEN 4 WHEN 'May' THEN 5 WHEN 'Jun' THEN 6 WHEN 'Jul' THEN 7 WHEN 'Aug' THEN 8 WHEN 'Sep' THEN 9 WHEN 'Oct' THEN 10 WHEN 'Nov' THEN 11 WHEN 'Dec' THEN 12 END, 2, '0' ) AS month, COUNT(DISTINCT id) AS distinct_email_count FROM enron_emailinfo WHERE SUBSTRING_INDEX(SUBSTRING_INDEX(date, ' ', 4), ' ', -1) = '2001' GROUP BY month ORDER BY month
SELECT mailbox, COUNT(*) AS cnt FROM enron_email WHERE people = 'allen-p' GROUP BY mailbox ORDER BY cnt DESC
SELECT e.`to`, COUNT(*) as cnt FROM enron_emailto e JOIN enron_emailinfo i ON e.id = i.id WHERE i.`from` = 'phillip.allen@enron.com' AND (i.subject LIKE 'RE:%' OR i.subject LIKE 'Re:%' OR i.subject LIKE 're:%') GROUP BY e.`to` ORDER BY cnt DESC LIMIT 5
WITH all_ids AS ( SELECT DISTINCT id FROM enron_emailto UNION SELECT DISTINCT id FROM enron_emailxto ), max_to AS ( SELECT id, MAX(nthto) AS max_nthto FROM enron_emailto GROUP BY id ), max_xto AS ( SELECT id, MAX(nthxto) AS max_nthxto FROM enron_emailxto GROUP BY id ), combined AS ( SELECT a.id, COALESCE(t.max_nthto, 0) AS max_nthto, COALESCE(x.max_nthxto, 0) AS max_nthxto, GREATEST(COALESCE(t.max_nthto, 0), COALESCE(x.max_nthxto, 0)) AS max_val FROM all_ids a LEFT JOIN max_to t ON a.id = t.id LEFT JOIN max_xto x ON a.id = x.id ) SELECT c.id, i.subject, c.max_nthto, c.max_nthxto FROM combined c LEFT JOIN enron_emailinfo i ON c.id = i.id ORDER BY c.max_val DESC, c.id ASC LIMIT 10
SELECT e2.`to`, COUNT(*) AS cnt FROM enron_emailinfo e1 JOIN enron_emailto e2 ON e1.id = e2.id WHERE e1.`from` IN ( 'enron.announcements@enron.com', '40enron@enron.com', 'announcements@datek.m0.net', 'administration.enron@enron.com', 'enron.general.announcements.enronxgate@enron.com', 'announcements.enron@enron.com', 'announce@inbox.nytimes.com', 'winnerannouncements@info.iwon.com', 'announcements@datek2.m0.net', 'general.announcement@enron.com', 'technology.enron@enron.com', 'admin.enron@enron.com', 'announcements.ubsw@enron.com' ) GROUP BY e2.`to` ORDER BY cnt DESC LIMIT 5
SELECT xfilename, COUNT(DISTINCT id) AS email_count FROM enron_source WHERE xfilename IS NOT NULL AND xfilename != '' GROUP BY xfilename ORDER BY email_count DESC, xfilename ASC LIMIT 5
WITH to_counts AS ( SELECT id, COUNT(DISTINCT LOWER(TRIM(`to`))) AS cnt_to FROM enron_emailto GROUP BY id ), xto_counts AS ( SELECT id, COUNT(DISTINCT TRIM(xto)) AS cnt_xto FROM enron_emailxto GROUP BY id ), all_ids AS ( SELECT DISTINCT id FROM enron_email ), combined AS ( SELECT a.id, COALESCE(t.cnt_to, 0) AS cnt_to, COALESCE(x.cnt_xto, 0) AS cnt_xto, ABS(COALESCE(t.cnt_to, 0) - COALESCE(x.cnt_xto, 0)) AS abs_diff FROM all_ids a LEFT JOIN to_counts t ON a.id = t.id LEFT JOIN xto_counts x ON a.id = x.id ) SELECT c.id, c.cnt_to, c.cnt_xto, c.abs_diff, LEFT(inf.`to`, 200) AS to_preview, LEFT(inf.xto, 200) AS xto_preview FROM combined c LEFT JOIN enron_emailinfo inf ON c.id = inf.id ORDER BY c.abs_diff DESC, c.id ASC LIMIT 10
SELECT LOWER(TRIM(ei.`from`)) AS sender, COUNT(DISTINCT LOWER(TRIM(et.`to`))) AS distinct_recipients FROM enron_emailinfo ei JOIN enron_emailto et ON ei.id = et.id WHERE ei.`from` IS NOT NULL AND TRIM(ei.`from`) != '' AND et.`to` IS NOT NULL AND TRIM(et.`to`) != '' GROUP BY LOWER(TRIM(ei.`from`)) ORDER BY distinct_recipients DESC, sender ASC LIMIT 1
SELECT people, COUNT(*) AS email_count FROM enron_email WHERE mailbox = 'deleted_items' GROUP BY people ORDER BY email_count DESC
SELECT ei.id AS current_id, ei.subject AS current_subject, eo.subject AS orig_subject, eo.`from` AS orig_from, eo.`to` AS orig_to, eo.xfrom AS orig_xfrom, eo.xto AS orig_xto FROM enron_emailinfo ei JOIN enron_emailorig eo ON ei.id = eo.id AND eo.nth = 1 WHERE LOWER(TRIM(ei.subject)) LIKE 're:%' ORDER BY ei.id ASC
SELECT LOWER(TRIM(e.`to`)) AS recipient_address, COUNT(DISTINCT e.id) AS distinct_email_count FROM enron_emailinfo ei INNER JOIN enron_emailto e ON ei.id = e.id WHERE ei.`date` LIKE '%Oct%2001%' GROUP BY LOWER(TRIM(e.`to`)) ORDER BY distinct_email_count DESC, recipient_address ASC LIMIT 5
SELECT e.people, e.mailbox, COUNT(DISTINCT e.id) AS cnt FROM enron_email e JOIN enron_emailinfo i ON e.id = i.id WHERE i.`from` = 'larry.campbell@enron.com' GROUP BY e.people, e.mailbox ORDER BY cnt DESC
SELECT people, COUNT(*) AS email_count FROM enron_email GROUP BY people ORDER BY email_count DESC LIMIT 5
SELECT COUNT(DISTINCT f.`from`) AS cnt FROM enron_emailinfo f WHERE EXISTS ( SELECT 1 FROM enron_emailto t WHERE t.`to` = f.`from` )
WITH sender_addresses AS ( SELECT DISTINCT TRIM(`from`) AS sender_addr FROM enron_emailinfo WHERE `from` IS NOT NULL AND TRIM(`from`) != '' ), recipient_addresses AS ( SELECT DISTINCT TRIM(`to`) AS recipient_addr FROM enron_emailto WHERE `to` IS NOT NULL AND TRIM(`to`) != '' ), senders_only AS ( SELECT s.sender_addr FROM sender_addresses s LEFT JOIN recipient_addresses r ON s.sender_addr = r.recipient_addr WHERE r.recipient_addr IS NULL ) SELECT so.sender_addr, COUNT(DISTINCT ei.id) AS sent_count FROM senders_only so JOIN enron_emailinfo ei ON TRIM(ei.`from`) = so.sender_addr GROUP BY so.sender_addr ORDER BY sent_count DESC, so.sender_addr ASC
SELECT subject, COUNT(*) AS reply_count FROM enron_emailorig WHERE subject IS NOT NULL AND subject != '' GROUP BY subject ORDER BY reply_count DESC LIMIT 10
WITH email_counts AS ( SELECT e.people, i.`from`, COUNT(DISTINCT e.id) AS email_count FROM enron_email e JOIN enron_emailinfo i ON e.id = i.id WHERE e.people IS NOT NULL AND e.people != '' AND i.`from` IS NOT NULL AND i.`from` != '' GROUP BY e.people, i.`from` ), ranked AS ( SELECT people, `from`, email_count, ROW_NUMBER() OVER (PARTITION BY people ORDER BY email_count DESC, `from` ASC) AS rn FROM email_counts ) SELECT people, `from`, email_count, rn FROM ranked WHERE rn <= 3 ORDER BY people ASC, rn ASC
SELECT ei.`from`, COUNT(*) AS email_count FROM enron_emailinfo ei WHERE ei.date IS NOT NULL AND SUBSTRING_INDEX(ei.date, ' ', 4) = 'Tue, 12 Dec 2000' GROUP BY ei.`from` ORDER BY email_count DESC LIMIT 5
WITH classified AS ( SELECT i.id, CASE WHEN i.`from` LIKE '%@enron.com' THEN 'internal' ELSE 'external' END AS category FROM enron_emailinfo i WHERE i.`from` IS NOT NULL AND TRIM(i.`from`) != '' ), stats AS ( SELECT category, COUNT(DISTINCT id) AS email_count FROM classified GROUP BY category ), total AS ( SELECT COUNT(DISTINCT id) AS total_count FROM enron_emailinfo WHERE `from` IS NOT NULL AND TRIM(`from`) != '' ) SELECT s.category, s.email_count, ROUND(s.email_count * 100.0 / t.total_count, 2) AS percentage FROM stats s, total t ORDER BY s.category ASC
WITH -- 每个people的规范化发件地址 sender AS ( SELECT DISTINCT e.people, ei.`from` AS address FROM enron_email e JOIN enron_emailinfo ei ON e.id = ei.id WHERE e.people IN ('campbell-l', 'allen-p', 'badeer-r') ), -- 每个people的规范化标准收件地址 recipient AS ( SELECT DISTINCT e.people, et.`to` AS address FROM enron_email e JOIN enron_emailto et ON e.id = et.id WHERE e.people IN ('campbell-l', 'allen-p', 'badeer-r') ), -- 合并为每个people的通信地址集合 person_address AS ( SELECT people, address FROM sender UNION SELECT people, address FROM recipient ), -- 统计每个地址出现在多少个不同people中 addr_people_count AS ( SELECT address, COUNT(DISTINCT people) AS cnt FROM person_address GROUP BY address HAVING cnt >= 2 ) SELECT a.address, a.cnt FROM addr_people_count a ORDER BY a.cnt DESC, a.address ASC
-- h08: NO SQL
WITH header_counts AS ( SELECT id, COUNT(*) AS header_count FROM enron_emailorig GROUP BY id ) SELECT ROUND(AVG(header_count), 4) AS avg_header_count, MAX(header_count) AS max_header_count, SUM(CASE WHEN header_count >= 3 THEN 1 ELSE 0 END) AS emails_with_at_least_3_headers FROM header_counts
WITH ranked AS ( SELECT people, mailbox, COUNT(*) AS cnt, RANK() OVER (PARTITION BY people ORDER BY COUNT(*) DESC) AS rnk FROM enron_email GROUP BY people, mailbox ) SELECT people, mailbox, cnt FROM ranked WHERE rnk = 1 ORDER BY people
